# -----------------------------------------------------------------------------
# SCENE
# -----------------------------------------------------------------------------

bpy.ops.object.select_all(action="SELECT")
bpy.ops.object.delete(use_global=False)

scene = bpy.context.scene
scene.render.engine = "BLENDER_EEVEE"
scene.render.resolution_x = 1600
scene.render.resolution_y = 1000
scene.render.resolution_percentage = 100
scene.render.image_settings.file_format = "PNG"
scene.render.film_transparent = False

world = bpy.data.worlds.get("World") or bpy.data.worlds.new("World")
scene.world = world
world.use_nodes = True
bg = world.node_tree.nodes.get("Background")
bg.inputs["Color"].default_value = (0.0012, 0.0020, 0.0040, 1.0)
bg.inputs["Strength"].default_value = 0.045

# -----------------------------------------------------------------------------
# COLLECTIONS
# -----------------------------------------------------------------------------

def get_coll(name):
    c = bpy.data.collections.get(name)
    if c is None:
        c = bpy.data.collections.new(name)
        scene.collection.children.link(c)
    return c

C_SHELL   = get_coll("R11C_SHELL")
C_STATOR  = get_coll("R11C_STATOR")
C_CHAMBER = get_coll("R11C_CHAMBER")
C_IRIS    = get_coll("R11C_IRIS")
C_ENERGY  = get_coll("R11C_ENERGY")
C_DETAIL  = get_coll("R11C_DETAIL")

def move_to(obj, coll):
    for c in list(obj.users_collection):
        c.objects.unlink(obj)
    coll.objects.link(obj)

# -----------------------------------------------------------------------------
# MATERIALS
# -----------------------------------------------------------------------------

def mat_principled(name, rgb, metallic=0.0, roughness=0.35):
    m = bpy.data.materials.new(name)
    m.use_nodes = True
    bsdf = m.node_tree.nodes.get("Principled BSDF")
    bsdf.inputs["Base Color"].default_value = (*rgb, 1.0)
    bsdf.inputs["Metallic"].default_value = metallic
    bsdf.inputs["Roughness"].default_value = roughness
    return m

def mat_emission(name, rgb, strength=5.0):
    m = bpy.data.materials.new(name)
    m.use_nodes = True
    nt = m.node_tree
    nt.nodes.clear()
    out = nt.nodes.new("ShaderNodeOutputMaterial")
    em = nt.nodes.new("ShaderNodeEmission")
    em.inputs["Color"].default_value = (*rgb, 1.0)
    em.inputs["Strength"].default_value = strength
    nt.links.new(em.outputs["Emission"], out.inputs["Surface"])
    return m

def mat_glass(name, rgb=(0.03,0.07,0.11), roughness=0.07, ior=1.46):
    m = bpy.data.materials.new(name)
    m.use_nodes = True
    nt = m.node_tree
    nt.nodes.clear()
    out = nt.nodes.new("ShaderNodeOutputMaterial")
    g = nt.nodes.new("ShaderNodeBsdfGlass")
    g.inputs["Color"].default_value = (*rgb, 1.0)
    g.inputs["Roughness"].default_value = roughness
    g.inputs["IOR"].default_value = ior
    nt.links.new(g.outputs["BSDF"], out.inputs["Surface"])
    return m

M_GRAPHITE  = mat_principled("R11C_Graphite", (0.015,0.022,0.033), 0.86, 0.24)
M_GRAPHITE2 = mat_principled("R11C_Graphite2", (0.040,0.055,0.075), 0.80, 0.30)
M_TITANIUM  = mat_principled("R11C_Titanium", (0.27,0.34,0.43), 0.92, 0.18)
M_EDGE      = mat_principled("R11C_Edge", (0.52,0.60,0.69), 0.94, 0.15)
M_COPPER    = mat_principled("R11C_Copper", (0.10,0.026,0.008), 0.82, 0.26)
M_CERAMIC   = mat_principled("R11C_BlackCeramic", (0.004,0.007,0.011), 0.18, 0.15)
M_GLASS     = mat_glass("R11C_SmokedGlass")
M_ICE       = mat_emission("R11C_IceWhite", (0.60,0.88,1.0), 9.0)
M_CYAN      = mat_emission("R11C_Cyan", (0.02,0.30,0.72), 4.0)
M_AMBER     = mat_emission("R11C_Amber", (1.0,0.12,0.02), 1.8)

# -----------------------------------------------------------------------------
# HELPERS
# -----------------------------------------------------------------------------

def bevel(obj, width=0.05, segments=3):
    mod = obj.modifiers.new("PrecisionBevel", "BEVEL")
    mod.width = width
    mod.segments = segments
    mod.limit_method = "ANGLE"
    mod.angle_limit = math.radians(22)

def weighted(obj):
    try:
        mod = obj.modifiers.new("WeightedNormal", "WEIGHTED_NORMAL")
        mod.keep_sharp = True
    except Exception:
        pass

def smooth(obj):
    if hasattr(obj.data, "polygons"):
        for p in obj.data.polygons:
            p.use_smooth = True

def cube(name, loc, size, mat, coll, rot=(0,0,0), bv=0.05):
    bpy.ops.mesh.primitive_cube_add(location=loc, rotation=rot)
    o = bpy.context.object
    o.name = name
    o.scale = (size[0]/2, size[1]/2, size[2]/2)
    bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)
    o.data.materials.append(mat)
    bevel(o, min(bv, min(size)*0.18), 3)
    weighted(o)
    move_to(o, coll)
    return o

def cyl(name, radius, depth, loc, mat, coll, verts=96, bv=0.035):
    bpy.ops.mesh.primitive_cylinder_add(vertices=verts, radius=radius, depth=depth, location=loc)
    o = bpy.context.object
    o.name = name
    o.data.materials.append(mat)
    bevel(o, bv, 3)
    weighted(o)
    smooth(o)
    move_to(o, coll)
    return o

def sphere(name, radius, loc, mat, coll, scale=(1,1,1), seg=64, rings=40):
    bpy.ops.mesh.primitive_uv_sphere_add(segments=seg, ring_count=rings, radius=radius, location=loc)
    o = bpy.context.object
    o.name = name
    o.scale = scale
    bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)
    o.data.materials.append(mat)
    smooth(o)
    move_to(o, coll)
    return o

def torus(name, major, minor, loc, mat, coll, major_seg=96, minor_seg=20):
    bpy.ops.mesh.primitive_torus_add(
        major_radius=major,
        minor_radius=minor,
        major_segments=major_seg,
        minor_segments=minor_seg,
        location=loc
    )
    o = bpy.context.object
    o.name = name
    o.data.materials.append(mat)
    smooth(o)
    move_to(o, coll)
    return o

def sculpted_shell(name, a0_deg, a1_deg, r_inner, r_outer, depth, z_front, z_back,
                   mat, coll, steps=72, camber=0.22, taper=0.08, skew=0.0):
    """
    Coherent cambered shell sector.
    Not a flat annular wedge:
    - front/back Z vary through the span
    - radii vary through the span
    - taper/skew break perfect circularity
    """
    a0 = math.radians(a0_deg)
    a1 = math.radians(a1_deg)
    verts = []
    faces = []

    # Four strips: front inner/outer, rear inner/outer
    for side in ("front","rear"):
        for i in range(steps+1):
            t = i/steps
            a = a0 + (a1-a0)*t
            wave = math.sin(math.pi*t)
            asym = (t-0.5)
            ri = r_inner * (1.0 - taper*wave + skew*asym)
            ro = r_outer * (1.0 + 0.45*taper*wave + 0.55*skew*asym)
            zbase = z_front if side=="front" else z_back
            z = zbase + (camber*wave if side=="front" else -0.55*camber*wave)
            verts.append((ri*math.cos(a), ri*math.sin(a), z))
            verts.append((ro*math.cos(a), ro*math.sin(a), z))

    n = (steps+1)*2
    # front/back faces
    for i in range(steps):
        b=i*2
        faces.append((b,b+1,b+3,b+2))
        t=n+i*2
        faces.append((t,t+2,t+3,t+1))
    # inner/outer walls
    for i in range(steps):
        b=i*2; t=n+i*2
        faces.append((b,b+2,t+2,t))
        faces.append((b+1,t+1,t+3,b+3))
    # end caps
    faces.append((0,n,n+1,1))
    e=steps*2
    faces.append((e,e+1,n+e+1,n+e))

    me=bpy.data.meshes.new(name+"_mesh")
    me.from_pydata(verts,[],faces)
    me.update()
    o=bpy.data.objects.new(name,me)
    coll.objects.link(o)
    o.data.materials.append(mat)
    bevel(o,0.055,3)
    weighted(o)
    smooth(o)
    return o

def radial_box(name, angle_deg, radius, tangential, radial, depth, z, mat, coll, angle_bias=0):
    a=math.radians(angle_deg)
    x=radius*math.cos(a); y=radius*math.sin(a)
    return cube(
        name,(x,y,z),(tangential,radial,depth),mat,coll,
        rot=(0,0,a-math.pi/2+math.radians(angle_bias)),
        bv=min(0.065,min(tangential,radial,depth)*0.14)
    )

