    radial_box(f"PowerSpineCap_{i}",a,r-0.32,tan*0.66,rad*0.36,0.12,z+dep*0.56,M_TITANIUM,C_DETAIL,angle_bias=bias)
    # inset dark copper conductors
    for j,off in enumerate((-0.12,0.12)):
        aa=math.radians(a)
        tx=-math.sin(aa); ty=math.cos(aa)
        x=(r+0.22)*math.cos(aa)+tx*off
        y=(r+0.22)*math.sin(aa)+ty*off
        cube(f"SpineCopper_{i}_{j}",(x,y,z-0.44),(0.055,0.56,0.11),M_COPPER,C_DETAIL,rot=(0,0,aa),bv=0.010)

