cam_data=bpy.data.cameras.new("R11C_Camera")
cam=bpy.data.objects.new("R11C_Camera",cam_data)
scene.collection.objects.link(cam)
scene.camera=cam
cam.data.sensor_width=36

def render(name,loc,target=(0,0,-0.35),lens=70):
    cam.location=loc
    cam.data.lens=lens
    look_at(cam,target)
    scene.render.filepath=os.path.join(RENDERS,name)
    bpy.ops.render.render(write_still=True)

render("R11C_FRONT.png",(0,-0.6,17.5),lens=74)
render("R11C_PRIMARY_3Q.png",(5.6,-5.6,15.2),target=(0,0,-0.45),lens=72)
render("R11C_OPPOSITE_3Q.png",(-5.8,5.0,14.8),target=(0,0,-0.55),lens=72)
render("R11C_SIDE_DEPTH.png",(12.8,-0.8,8.4),target=(0,0,-0.80),lens=76)

saved={}
for o in scene.objects:
    if o.type=="LIGHT":
        saved[o.name]=o.data.energy
        if o.name in ("Key","Fill","Rim"):
            o.data.energy*=0.26
        elif o.name=="Internal":
            o.data.energy*=1.40
render("R11C_DARK_ENERGY.png",(5.6,-5.6,15.2),target=(0,0,-0.45),lens=72)
