# -----------------------------------------------------------------------------
# SAVE / EXPORT
# -----------------------------------------------------------------------------

blend_path=os.path.join(OUT,"R11C_FLAGSHIP_REACTOR_SOURCE.blend")
bpy.ops.wm.save_as_mainfile(filepath=blend_path)

def export_collection(coll,filename):
    bpy.ops.object.select_all(action="DESELECT")
    objs=[o for o in coll.all_objects if o.type in {"MESH","EMPTY"}]
    for o in objs: o.select_set(True)
    if not objs: return
    bpy.context.view_layer.objects.active=objs[0]
    bpy.ops.export_scene.gltf(
        filepath=os.path.join(ASSETS,filename),
        export_format="GLB",
        use_selection=True,
        export_apply=True,
        export_yup=True
    )

exports=[
    (C_SHELL,"ev_core_r11c_shell.glb"),
    (C_STATOR,"ev_core_r11c_stator.glb"),
    (C_CHAMBER,"ev_core_r11c_chamber.glb"),
    (C_IRIS,"ev_core_r11c_iris.glb"),
    (C_ENERGY,"ev_core_r11c_energy.glb"),
    (C_DETAIL,"ev_core_r11c_detail.glb"),
]
for c,f in exports:
    export_collection(c,f)

# triangle count
dg=bpy.context.evaluated_depsgraph_get()
tris=0
for o in scene.objects:
    if o.type=="MESH":
        ev=o.evaluated_get(dg)
        me=ev.to_mesh()
        me.calc_loop_triangles()
        tris+=len(me.loop_triangles)
        ev.to_mesh_clear()

report=os.path.join(OUT,"R11C_BUILD_REPORT.txt")
with open(report,"w",encoding="utf-8") as f:
    f.write("E.V. R11C FLAGSHIP REACTOR BUILD REPORT\n")
    f.write("=====================================\n\n")
    f.write(f"Blender: {bpy.app.version_string}\n")
    f.write(f"Evaluated triangles: {tris}\n")
    f.write("Live E.V. GUI modified: NO\n")
    f.write("Major design: 3 interlocking sculpted masses, deep chamber, 4 power spines.\n\n")
    f.write("Renders:\n")
    for n in ["R11C_FRONT.png","R11C_PRIMARY_3Q.png","R11C_OPPOSITE_3Q.png","R11C_SIDE_DEPTH.png","R11C_DARK_ENERGY.png"]:
        f.write("- "+os.path.join(RENDERS,n)+"\n")
    f.write("\nAssets:\n")
    for _,n in exports:
        p=os.path.join(ASSETS,n)
        f.write(f"- {p} ({os.path.getsize(p) if os.path.exists(p) else 0} bytes)\n")

print("\nR11C FLAGSHIP REACTOR COMPLETE")
